<?phprequire_once 'session_check.php';check_session(['Admin', 'Manager']);// Ensure only Admin & Manager can accessif (!isset($_SESSION['username']) || ($_SESSION['uType'] !== 'Admin' && $_SESSION['uType'] !== 'Manager')) {    $_SESSION['error'] = "Access denied!";    header("Location: dashboard.php");    exit();}// Set headers for CSV downloadheader('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename=product_import_template.csv');// Create a file handle for writing to the output stream$output = fopen('php://output', 'w');// Add UTF-8 BOM to fix Excel encoding issuesfprintf($output, chr(0xEF).chr(0xBB).chr(0xBF));// Write header rowfputcsv($output, [    'product_name',    'allergens',    'ingredients',    'healthy_option',    'recipe',    'image_path',    'categories',    'groups']);// Write sample data rowfputcsv($output, [    'Sample Product',    'Nuts, Dairy, Gluten',    'Water, Flour, Sugar, Salt',    'Green', // Valid options: Green, Amber, Red    'Mix ingredients, Bake at 180°C for 30 minutes',    'uploads/sample.jpg',    'Breakfast, Healthy Options',    'Group A, Group B']);// Write an empty row for users to fillfputcsv($output, [    '',    '',    '',    '',    '',    '',    '',    '']);fclose($output);exit(); // Important: stop further execution after output?>